---开关timeline相机
---@param state boolean 是否启用
function PreDownloadCatShareDialog:SetTimelineCameraEnable(state)
    ---@type SceneInstance
    local sceneIns = SceneManagement:GetInstance():GetSceneInstance(Constants.IdSceneSetting21)
    if not isNull(sceneIns) then
        ---@type UnityEngine.GameObject
        local throwGO = sceneIns:GetCacheObjectByName("throw_loc")
        ---@type UnityEngine.GameObject
        local camGO = throwGO.transform:Find("throw_part03_timeline/throw_part03_cam/cam")
        if isNull(camGO) then return end
        ---@type UnityEngine.Camera
        local camComp = camGO:GetComponent(typeof(Camera))
        camComp.enabled = checkBool(state)
    end
end
--endregion private

return PreDownloadCatShareDialog